import unittest

from solucao import so_letra
from solucao import so_numero


class TestSoNumerosOuSoLetras(unittest.TestCase):
    def test_numero_puro(self):
        """so_numero devolve True para texto so de numeros"""
        self.assertEqual(so_numero("123"), True)

    def test_numero_com_letra(self):
        """so_numero devolve False quando tem letra no meio"""
        self.assertEqual(so_numero("12a"), False)

    def test_texto_vazio_nao_e_numero(self):
        """so_numero devolve False para o texto vazio"""
        self.assertEqual(so_numero(""), False)

    def test_letra_pura(self):
        """so_letra devolve True para texto so de letras"""
        self.assertEqual(so_letra("abc"), True)

    def test_letra_com_numero(self):
        """so_letra devolve False quando tem numero no meio"""
        self.assertEqual(so_letra("a1"), False)

    def test_texto_vazio_nao_e_letra(self):
        """so_letra devolve False para o texto vazio"""
        self.assertEqual(so_letra(""), False)

